def tinh_tong_so(tap_hop):
    try:
        bo_lap = iter(tap_hop)
    except TypeError:
        return None
    tong = 0.0
    for x in bo_lap:
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            tong += x
    return tong

dau_vao = [
    ("danh sách", [10, 20.5, 30]),
    ("bộ tuple", (5, 15.0, 25)),
    ("dãy range", range(1, 4)),
    ("có chứa bool", [10, True, 20]),
    ("số đơn", 100),
]

for ten, gia_tri in dau_vao:
    kq = tinh_tong_so(gia_tri)
    print(f"{ten:<14}: tổng = {kq}")
